1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.time.LocalDate;
4	
5	import net.officefloor.plugin.variable.Out;
6	import net.officefloor.plugin.variable.Val;
7	import org.springframework.samples.petclinic.mapper.OwnerMapper;
8	import org.springframework.samples.petclinic.model.Owner;
9	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
10	import org.springframework.samples.petclinic.repository.OwnerRepository;
11	
12	public class BuildOwner {
13	
14	    public void service(@Val OwnerFieldsDto request, @Val Household.Id householdId,
15	            OwnerMapper ownerMapper, OwnerRepository ownerRepository, Out<Owner> built) {
16	        Owner owner = ownerMapper.toOwner(request);
17	        // Default an unsupplied registration date to the server's current date.
18	        if (owner.getRegistrationDate() == null) {
19	            owner.setRegistrationDate(LocalDate.now());
20	        }
21	        owner.setCustomerCode(nextCustomerCode(owner.getCity(), owner.getLastName(), ownerRepository));
22	        // Record how many existing owners already share this first+last name (case-insensitive),
23	        // counted before this owner is persisted so the value is fixed at creation time.
24	        owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName(), ownerRepository));
25	        // Join a shared household when the gate resolved an identifier.
26	        if (householdId != null && householdId.isPresent()) {
27	            owner.setHouseholdId(householdId.value());
28	        }
29	        built.set(owner);
30	    }
31	
32	    /**
33	     * Build the '<CITY3>-<LAST3>-<NNNN>' customer code: CITY3 is the upper-cased first three
34	     * letters of the city, LAST3 the upper-cased first three letters of the last name, and NNNN
35	     * a per-city 4-digit zero-padded sequence equal to one more than the number of owners
36	     * already in that city (e.g. 'LON-SMI-0007').
37	     */
38	    private static String nextCustomerCode(String city, String lastName, OwnerRepository ownerRepository) {
39	        String city3 = city.substring(0, Math.min(3, city.length())).toUpperCase();
40	        String last3 = lastName.substring(0, Math.min(3, lastName.length())).toUpperCase();
41	        int sequence = countOwnersInCity(city, ownerRepository) + 1;
42	        return String.format("%s-%s-%04d", city3, last3, sequence);
43	    }
44	
45	    /**
46	     * Count the existing owners in the given city, compared case-insensitively.
47	     */
48	    private static int countOwnersInCity(String city, OwnerRepository ownerRepository) {
49	        int count = 0;
50	        for (Owner existing : ownerRepository.findAll()) {
51	            if (city.equalsIgnoreCase(existing.getCity())) {
52	                count++;
53	            }
54	        }
55	        return count;
56	    }
57	
58	    /**
59	     * Count the existing owners whose first and last names both match the given names,
60	     * compared case-insensitively.
61	     */
62	    private static int countNamesakes(String firstName, String lastName,
63	            OwnerRepository ownerRepository) {
64	        int count = 0;
65	        for (Owner existing : ownerRepository.findAll()) {
66	            if (firstName.equalsIgnoreCase(existing.getFirstName())
67	                    && lastName.equalsIgnoreCase(existing.getLastName())) {
68	                count++;
69	            }
70	        }
71	        return count;
72	    }
73	}
