1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.time.LocalDate;
4	
5	import net.officefloor.plugin.variable.Val;
6	import org.springframework.samples.petclinic.model.Owner;
7	import org.springframework.samples.petclinic.repository.OwnerRepository;
8	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
9	import org.springframework.samples.petclinic.rest.escalation.DailyOwnerLimitException;
10	
11	/**
12	 * Runs after {@link ValidateCityCapacity} and before {@link BuildOwner}. A read-only
13	 * validation gate: rejects the create with a 429 when 100 or more owners have already been
14	 * created today (by {@code registrationDate}, compared against the server's current date),
15	 * so no more than 100 owners can be registered per day. Publishes nothing; it only
16	 * escalates when the limit is reached.
17	 */
18	public class ValidateDailyOwnerLimit {
19	
20	    private static final int DAILY_LIMIT = 100;
21	
22	    public void service(@Val OwnerFieldsDto request, OwnerRepository ownerRepository)
23	            throws DailyOwnerLimitException {
24	        LocalDate today = LocalDate.now();
25	        int count = 0;
26	        for (Owner existing : ownerRepository.findAll()) {
27	            if (today.equals(existing.getRegistrationDate())) {
28	                count++;
29	            }
30	        }
31	        if (count >= DAILY_LIMIT) {
32	            throw new DailyOwnerLimitException(
33	                    DAILY_LIMIT + " or more owners have already been created today");
34	        }
35	    }
36	}
