27	/**
28	 * Simple JavaBean domain object representing an owner.
29	 *
30	 * @author Ken Krebs
31	 * @author Juergen Hoeller
32	 * @author Sam Brannen
33	 * @author Michael Isvy
34	 */
35	@Entity
36	@Table(name = "owners")
37	public class Owner extends Person {
38	    @Column(name = "address")
39	    @NotEmpty
40	    private String address;
41	
42	    @Column(name = "city")
43	    @NotEmpty
44	    private String city;
45	
46	    @Column(name = "telephone")
47	    @NotEmpty
48	    @Pattern(regexp = "^\\+[0-9]{8,15}$", message = "Phone number must be in E.164 form (+ followed by 8 to 15 digits)")
49	    private String telephone;
50	
51	    @Column(name = "email")
52	    private String email;
53	
54	    @Column(name = "registration_date")
55	    private LocalDate registrationDate;
56	
57	    @Column(name = "customer_code")
58	    private String customerCode;
59	
60	    @Column(name = "household_id")
61	    private String householdId;
62	
63	    @Column(name = "namesake_count")
64	    private Integer namesakeCount;
65	
66	    @OneToMany(cascade = CascadeType.ALL, mappedBy = "owner", fetch = FetchType.EAGER)
67	    private Set<Pet> pets;
68	
69	    public String getAddress() {
70	        return this.address;
71	    }
72	
73	    public void setAddress(String address) {
74	        this.address = address;
75	    }
76	
77	    public String getCity() {
78	        return this.city;
79	    }
80	
81	    public void setCity(String city) {
82	        this.city = city;
83	    }
84	
85	    public String getTelephone() {
86	        return this.telephone;
87	    }
88	
89	    public void setTelephone(String telephone) {
90	        this.telephone = telephone;
91	    }
92	
93	    public String getEmail() {
94	        return this.email;
95	    }
96	
97	    public void setEmail(String email) {
98	        this.email = email;
99	    }
100	
101	    public LocalDate getRegistrationDate() {
102	        return this.registrationDate;
103	    }
104	
105	    public void setRegistrationDate(LocalDate registrationDate) {
106	        this.registrationDate = registrationDate;
107	    }
108	
109	    public String getCustomerCode() {
110	        return this.customerCode;
111	    }
112	
113	    public void setCustomerCode(String customerCode) {
114	        this.customerCode = customerCode;
115	    }
116	
117	    public String getHouseholdId() {
118	        return this.householdId;
119	    }
120	
121	    public void setHouseholdId(String householdId) {
122	        this.householdId = householdId;
123	    }
124	
125	    public Integer getNamesakeCount() {
126	        return this.namesakeCount;
127	    }
128	
129	    public void setNamesakeCount(Integer namesakeCount) {
130	        this.namesakeCount = namesakeCount;
131	    }
132	
133	    /**
134	     * The owner's name formatted as {@code 'LastName, FirstName'} from the stored names.
135	     * Not persisted — derived from {@link #getLastName()} and {@link #getFirstName()}.
136	     */
137	    @Transient
138	    public String getDisplayName() {
139	        return this.getLastName() + ", " + this.getFirstName();
140	    }
141	
142	    /**
143	     * The owner's initials: the upper-cased first letters of firstName and lastName,
144	     * dot-separated with a trailing dot (e.g. {@code 'J.S.'}).
145	     * Not persisted — derived from {@link #getFirstName()} and {@link #getLastName()}.
146	     */
147	    @Transient
148	    public String getInitials() {
149	        return Character.toUpperCase(this.getFirstName().charAt(0)) + "."
150	            + Character.toUpperCase(this.getLastName().charAt(0)) + ".";
151	    }
152	
153	    /**
154	     * The owner's membership number, formatted {@code '<customerCode>-M<YY>'} where YY is
155	     * the last two digits of the {@link #getRegistrationDate() registrationDate} year
156	     * (e.g. {@code 'LON-SMI-0007-M26'}).
157	     * Not persisted — derived from {@link #getCustomerCode()} and {@link #getRegistrationDate()}.
158	     */
159	    @Transient
160	    public String getMembershipNumber() {
161	        return this.customerCode + "-M" + String.format("%02d", this.registrationDate.getYear() % 100);
162	    }
163	
164	    /**
165	     * The owner's membership tier: {@code 'SILVER'} when {@link #getNamesakeCount() namesakeCount}
166	     * is 0 and an {@link #getEmail() email} is present, otherwise {@code 'BRONZE'}.
167	     * Not persisted — derived from {@link #getNamesakeCount()} and {@link #getEmail()}.
168	     */
169	    @Transient
170	    public String getMembershipTier() {
171	        boolean uniqueName = this.namesakeCount != null && this.namesakeCount == 0;
172	        boolean hasEmail = this.email != null && !this.email.isBlank();
173	        return (uniqueName && hasEmail) ? "SILVER" : "BRONZE";
174	    }
175	
176	    /**
177	     * Fixed city-to-region table used to derive {@link #getLocality() locality}.
178	     */
179	    private static final Map<String, String> CITY_REGION = Map.of(
180	        "Sydney", "NSW", "Melbourne", "VIC", "Brisbane", "QLD");
181	
182	    /**
183	     * The owner's locality: the canonical region derived from {@link #getCity() city}
184	     * using the fixed {@link #CITY_REGION} table (Sydney->NSW, Melbourne->VIC,
185	     * Brisbane->QLD), or {@code 'UNKNOWN'} when the city is not in the table.
186	     * Not persisted — derived from {@link #getCity()}.
187	     */
188	    @Transient
189	    public String getLocality() {
190	        return CITY_REGION.getOrDefault(this.city, "UNKNOWN");
191	    }
192	
193	    protected Set<Pet> getPetsInternal() {
194	        if (this.pets == null) {
195	            this.pets = new HashSet<>();
196	        }
197	        return this.pets;
198	    }
199	
200	    protected void setPetsInternal(Set<Pet> pets) {
201	        this.pets = pets;
202	    }
203	
204	    public List<Pet> getPets() {
205	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
206	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
207	        return Collections.unmodifiableList(sortedPets);
208	    }
209	
210	    public void setPets(List<Pet> pets) {
211	        this.pets = new HashSet<>(pets);
212	    }
213	
214	    public void addPet(Pet pet) {
215	        getPetsInternal().add(pet);
216	        pet.setOwner(this);
217	    }
218	
219	    /**
220	     * Return the Pet with the given name, or null if none found for this Owner.
221	     *
222	     * @param name to test
223	     * @return true if pet name is already in use
224	     */
225	    public Pet getPet(String name) {
226	        return getPet(name, false);
227	    }
228	
229	    /**
230	     * Return the Pet with the given name, or null if none found for this Owner.
231	     *
232	     * @param name to test
233	     * @return true if pet name is already in use
234	     */
235	    public Pet getPet(String name, boolean ignoreNew) {
236	        name = name.toLowerCase();
237	        for (Pet pet : getPetsInternal()) {
238	            if (!ignoreNew || !pet.isNew()) {
239	                String compName = pet.getName();
240	                compName = compName.toLowerCase();
241	                if (compName.equals(name)) {
242	                    return pet;
243	                }
244	            }
245	        }
246	        return null;
247	    }
248	
249	    public Pet getPet(Integer petId) {
250	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
251	    }
252	
253	    @Override
254	    public String toString() {
255	        return new ToStringCreator(this)
256	
257	            .append("id", this.getId())
258	            .append("new", this.isNew())
259	            .append("lastName", this.getLastName())
260	            .append("firstName", this.getFirstName())
261	            .append("address", this.address)
262	            .append("city", this.city)
263	            .append("telephone", this.telephone)
264	            .toString();
265	    }
266	}
