3	/**
4	 * Thrown by the owner-create pipeline when 100 or more owners have already been created
5	 * today (by {@code registrationDate}), so the daily create limit has been reached.
6	 *
7	 * <p>Handled by {@link DailyOwnerLimitExceptionHandler}, which responds 429.
8	 */
9	public class DailyOwnerLimitException extends Exception {
